import 'il_localities.dart';
import 'region.dart';

export 'il_localities.dart' show israelLocalities;

/// Israel: the first region of Find a vet.
///
/// The bounds match the server's (`supabase/functions/_shared/regions/il.ts`).
/// The localities (`il_localities.dart`, generated by
/// `tool/gen_il_localities.py`) are the centres of every city, town and
/// local council, enough to search "near Rehovot" with no server call;
/// anything else (a street, a postcode, a smaller place) goes to the
/// server's geocoder. Dog parks store their codes.
final israelRegion = VetRegion(
  code: 'IL',
  bounds: GeoBounds(south: 29.3, west: 34.2, north: 33.5, east: 35.95),
  languages: ['he', 'en'],
  center: GeoPoint(31.77, 35.0),
  emergencyLadderM: [10000, 25000, 50000, 120000],
  longTermLadderM: [5000, 10000, 20000],
  localities: israelLocalities,
);
